  SWIG_InstallConstants(d,swig_const_table);
  
  SWIG_Python_SetConstant(d, "SHARED_PTR_DISOWN",SWIG_From_int(static_cast< int >(0)));
  
  
  PyDateTime_IMPORT;
  
  RobotRaconteur::PythonTypeSupport_Init();
  
  RobotRaconteur::RobotRaconteurNode::s()->SetDynamicServiceFactory(RR_MAKE_SHARED<RobotRaconteur::WrappedDynamicServiceFactory>());
  RobotRaconteur::RobotRaconteurNode::s()->SetThreadPoolFactory(RR_MAKE_SHARED<RobotRaconteur::PythonThreadPoolFactory>());
  //RobotRaconteur::RobotRaconteurNode::s()->UnregisterServiceType("RobotRaconteurServiceIndex");
  //RobotRaconteur::RobotRaconteurNode::s()->RegisterServiceType(RR_MAKE_SHARED<RobotRaconteur::WrappedServiceFactory>(RR_MAKE_SHARED<RobotRaconteurServiceIndex::RobotRaconteurServiceIndexFactory>()->DefString()));
  
  SWIG_Python_SetConstant(d, "DataTypes_void_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_void_t)));
  SWIG_Python_SetConstant(d, "DataTypes_double_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_double_t)));
  SWIG_Python_SetConstant(d, "DataTypes_single_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_single_t)));
  SWIG_Python_SetConstant(d, "DataTypes_int8_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_int8_t)));
  SWIG_Python_SetConstant(d, "DataTypes_uint8_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_uint8_t)));
  SWIG_Python_SetConstant(d, "DataTypes_int16_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_int16_t)));
  SWIG_Python_SetConstant(d, "DataTypes_uint16_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_uint16_t)));
  SWIG_Python_SetConstant(d, "DataTypes_int32_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_int32_t)));
  SWIG_Python_SetConstant(d, "DataTypes_uint32_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_uint32_t)));
  SWIG_Python_SetConstant(d, "DataTypes_int64_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_int64_t)));
  SWIG_Python_SetConstant(d, "DataTypes_uint64_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_uint64_t)));
  SWIG_Python_SetConstant(d, "DataTypes_string_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_string_t)));
  SWIG_Python_SetConstant(d, "DataTypes_cdouble_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_cdouble_t)));
  SWIG_Python_SetConstant(d, "DataTypes_csingle_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_csingle_t)));
  SWIG_Python_SetConstant(d, "DataTypes_bool_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_bool_t)));
  SWIG_Python_SetConstant(d, "DataTypes_structure_t",SWIG_From_int(static_cast< int >(RobotRaconteur::DataTypes_structure_t)));
